//! Values supplied by insertion forms, shared by both document adapters.

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Parameters {
    None,
    Table {
        rows: usize,
        columns: usize,
        header: bool,
    },
    Link {
        text: String,
        href: String,
    },
    Image {
        src: String,
        alt: String,
    },
    Text(String),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FormKind {
    Table,
    Link,
    Image,
    Mermaid,
    InlineMath,
    BlockMath,
    Endnote,
    Footnote,
}

impl FormKind {
    pub fn for_command(id: &str) -> Option<Self> {
        Some(match id {
            "insert.table" => Self::Table,
            "insert.link" => Self::Link,
            "insert.image" => Self::Image,
            "insert.mermaid" => Self::Mermaid,
            "insert.math-inline" => Self::InlineMath,
            "insert.math-block" => Self::BlockMath,
            "insert.endnote" => Self::Endnote,
            "insert.footnote" => Self::Footnote,
            _ => return None,
        })
    }
    pub fn title(self) -> &'static str {
        match self {
            Self::Table => "Insert a table",
            Self::Link => "Insert a link",
            Self::Image => "Insert an image",
            Self::Mermaid => "Insert a diagram",
            Self::InlineMath => "Inline equation",
            Self::BlockMath => "Display equation",
            Self::Endnote => "Insert an endnote",
            Self::Footnote => "Insert a footnote",
        }
    }
    pub fn primary_label(self) -> &'static str {
        match self {
            Self::Table => "Rows",
            Self::Link => "Link text",
            Self::Image => "Image URL",
            Self::Mermaid => "Mermaid source",
            Self::InlineMath | Self::BlockMath => "LaTeX source",
            Self::Endnote | Self::Footnote => "Note text",
        }
    }
    pub fn secondary_label(self) -> Option<&'static str> {
        match self {
            Self::Table => Some("Columns"),
            Self::Link => Some("URL"),
            Self::Image => Some("Alternative text"),
            _ => None,
        }
    }
    pub fn multiline(self) -> bool {
        matches!(
            self,
            Self::Mermaid | Self::InlineMath | Self::BlockMath | Self::Endnote | Self::Footnote
        )
    }
    pub fn values(
        self,
        primary: &str,
        secondary: &str,
        header: bool,
    ) -> Result<Parameters, &'static str> {
        Ok(match self {
            Self::Table => {
                let rows = primary
                    .trim()
                    .parse::<usize>()
                    .ok()
                    .filter(|v| (1..=100).contains(v));
                let columns = secondary
                    .trim()
                    .parse::<usize>()
                    .ok()
                    .filter(|v| (1..=100).contains(v));
                Parameters::Table {
                    rows: rows.ok_or("Use between 1 and 100 rows.")?,
                    columns: columns.ok_or("Use between 1 and 100 columns.")?,
                    header,
                }
            }
            Self::Link => Parameters::Link {
                text: required(primary, "Enter the link text.")?,
                href: required(secondary, "Enter a URL.")?,
            },
            Self::Image => Parameters::Image {
                src: required(primary, "Enter an image URL.")?,
                alt: secondary.to_owned(),
            },
            _ => Parameters::Text(required(primary, "Enter the content to insert.")?),
        })
    }
}

fn required(value: &str, message: &'static str) -> Result<String, &'static str> {
    if value.trim().is_empty() {
        Err(message)
    } else {
        Ok(value.to_owned())
    }
}
